<?php
if(!defined('ABSPATH'))exit;global $wpdb;
$te=ICD_Visitas_Database::table('escolas');$tm=ICD_Visitas_Database::table('mediadores');$tvinc=ICD_Visitas_Database::table('vinculos');$tpg=ICD_Visitas_Database::table('pedagogas');$tv=ICD_Visitas_Database::table('visitas');$tp=ICD_Visitas_Database::table('participantes');$tvp=ICD_Visitas_Database::table('visita_pedagogas');
$schools=$wpdb->get_results("SELECT id,nome FROM $te WHERE ativo=1 ORDER BY nome");$meds=$wpdb->get_results("SELECT id,nome FROM $tm WHERE ativo=1 ORDER BY nome");$peds=$wpdb->get_results("SELECT id,nome FROM $tpg WHERE ativo=1 ORDER BY nome");$currentPed=ICD_Visitas_Helpers::current_pedagoga_id();$map=[];foreach($wpdb->get_results("SELECT escola_id,mediador_id FROM $tvinc WHERE ativo=1") as $x)$map[$x->mediador_id][]=(int)$x->escola_id;
$edit_id=absint($_GET['editar']??0);$edit=null;$editMeds=[];$editPeds=[];
if($edit_id){$edit=$wpdb->get_row($wpdb->prepare("SELECT * FROM $tv WHERE id=%d",$edit_id));if($edit){$editMeds=array_map('intval',$wpdb->get_col($wpdb->prepare("SELECT mediador_id FROM $tp WHERE visita_id=%d",$edit_id)));$editPeds=array_map('intval',$wpdb->get_col($wpdb->prepare("SELECT pedagoga_id FROM $tvp WHERE visita_id=%d",$edit_id)));}}
?>
<div class="icd-shell"><header class="icd-app-header"><div class="icd-brand"><img src="<?php echo esc_url(ICD_VISITAS_URL.'assets/logo.svg');?>" alt=""><div><small>Supervisão pedagógica</small><h2><?php echo $edit?'Editar visita':'Registrar visita';?></h2></div></div></header>
<?php if(isset($_GET['saved'])):?><div class="icd-success">Visita registrada com sucesso.</div><?php endif;?><?php if(isset($_GET['updated'])):?><div class="icd-success">Visita atualizada com sucesso.</div><?php endif;?>
<form class="icd-mobile-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><?php wp_nonce_field('icd_save_visita');?><input type="hidden" name="action" value="icd_save_visita"><input type="hidden" name="id" value="<?php echo (int)($edit->id??0);?>"><input type="hidden" name="tipo" value="acompanhamento"><input type="hidden" name="origem" value="<?php echo esc_attr($edit->origem??'manual');?>"><input type="hidden" name="redirect_to" value="<?php echo esc_url(get_permalink());?>">
<label>Escola<select required name="escola_id" id="icd-school"><option value="">Selecione</option><?php foreach($schools as $x)echo '<option value="'.$x->id.'" '.selected((int)($edit->escola_id??0),$x->id,false).'>'.esc_html($x->nome).'</option>';?></select></label>
<div class="icd-two"><label>Data<input required type="date" name="data_visita" value="<?php echo esc_attr($edit->data_visita??current_time('Y-m-d'));?>"></label><label>Turno<select name="turno"><?php foreach(['manha'=>'Manhã','tarde'=>'Tarde','noite'=>'Noite','integral'=>'Integral'] as $k=>$lab)echo '<option value="'.$k.'" '.selected($edit->turno??'manha',$k,false).'>'.$lab.'</option>';?></select></label></div>
<label>Status<select name="status"><?php foreach(['realizada'=>'Realizada','programada'=>'Programada','confirmada'=>'Confirmada','nao_realizada'=>'Não realizada','cancelada'=>'Cancelada','reagendada'=>'Reagendada'] as $k=>$lab)echo '<option value="'.$k.'" '.selected($edit->status??'realizada',$k,false).'>'.$lab.'</option>';?></select></label>
<fieldset><legend>Pedagoga responsável pela visita</legend><?php if(!$peds):?><p>Cadastre uma pedagoga no painel administrativo.</p><?php endif;foreach($peds as $x):$checked=$edit?in_array((int)$x->id,$editPeds,true):((int)$currentPed===(int)$x->id);?><label class="icd-check"><input type="checkbox" name="pedagogas[]" value="<?php echo (int)$x->id;?>" <?php checked($checked);?>> <?php echo esc_html($x->nome);?></label><?php endforeach;?></fieldset>
<fieldset><legend>Mediadores acompanhados</legend><small class="icd-help">Eles aparecem automaticamente conforme a escola selecionada.</small><?php foreach($meds as $x):$ids=implode(',',array_map('intval',$map[$x->id]??[]));?><label class="icd-check icd-mediator-option" data-schools="<?php echo esc_attr($ids);?>"><input type="checkbox" name="mediadores[]" value="<?php echo (int)$x->id;?>" <?php checked(in_array((int)$x->id,$editMeds,true));?>> <?php echo esc_html($x->nome);?></label><?php endforeach;?></fieldset>
<label>Observações da visita<textarea name="observacoes" rows="7" placeholder="O que foi observado? Como está o trabalho dos mediadores? Houve orientações ou encaminhamentos? Quais pontos precisam de acompanhamento?"><?php echo esc_textarea($edit->observacoes??'');?></textarea></label><button class="icd-submit"><?php echo $edit?'Salvar alterações':'Registrar visita';?></button><?php if($edit):?><a class="icd-secondary-link" href="<?php echo esc_url(get_permalink());?>">Cancelar edição</a><?php endif;?></form><?php require ICD_VISITAS_DIR.'public/nav.php';?></div>
<script>document.addEventListener('DOMContentLoaded',function(){const s=document.getElementById('icd-school');const opts=[...document.querySelectorAll('.icd-mediator-option')];function f(){const id=s?s.value:'';opts.forEach(o=>{const ok=id&&o.dataset.schools.split(',').includes(id);o.style.display=ok?'flex':'none';if(!ok)o.querySelector('input').checked=false;});}if(s){s.addEventListener('change',f);f();}});</script>
